parameters.jsCode:
// Combina datos del candidato con la respuesta de GPT
const out = [];
const inputs = $input.all();
const originals = $('Fetch new candidates').all();
for (let i = 0; i < inputs.length; i++) {
  const cand = originals[i].json;
  const gptRaw = inputs[i].json;
  let scoring = {};
  try {
    const content = gptRaw.choices[0].message.content;
    scoring = JSON.parse(content);
  } catch (e) {
    scoring = {reject_reason: 'gpt_parse_error', horror_score: 0, quality_score: 0};
  }
  // Coste estimado (gpt-4o-mini): $0.15/1M in, $0.60/1M out (approx)
  const usage = gptRaw.usage || {};
  const cost = ((usage.prompt_tokens || 0) * 0.15 / 1e6) + ((usage.completion_tokens || 0) * 0.60 / 1e6);
  out.push({json: {
    candidate_id: cand.id,
    reddit_id: cand.reddit_id,
    horror_score: scoring.horror_score || 0,
    quality_score: scoring.quality_score || 0,
    shorts_potential: scoring.shorts_potential || 0,
    estimated_segments: scoring.estimated_segments || 4,
    main_themes: scoring.main_themes || [],
    summary_es: scoring.summary_es || '',
    reject_reason: scoring.reject_reason,
    llm_cost_usd: Number(cost.toFixed(5)),
    llm_tokens_in: usage.prompt_tokens || 0,
    llm_tokens_out: usage.completion_tokens || 0,
  }});
}
return out;

